export const createMessages = catchAsync(async (req, res) => {
  const { body } = req;
  body.createdBy = req.user._id;
  body.updatedBy = req.user._id;
  const options = {};
  const messages = await messagesService.createMessages(body, options);

  if (body.chatId) {
    Chats.findById(body.chatId)
      .then((chat) => {
        if (chat) {
          const senderId = req.user ? req.user._id : body.senderId;
          const recipientId = String(chat.customerId) === String(senderId) ? chat.vendorId : chat.customerId;
          const senderName = req.user ? req.user.fullName || req.user.name || 'User' : 'Someone';
          notificationService
            .notifyNewChatMessage({
              recipientUserId: recipientId,
              senderUserId: senderId,
              senderName,
              messageText: body.message || '',
              chatId: body.chatId,
            })
            .catch(() => {});
        }
      })
      .catch(() => {});
  }

  return res.status(httpStatus.CREATED).send({ results: messages });
});

export const updateMessages = catchAsync(async (req, res) => {
  const { body } = req;
  body.updatedBy = req.user;
  const { messagesId } = req.params;
  const filter = {
    _id: messagesId,
  };
  const options = { new: true };
  const messages = await messagesService.updateMessages(filter, body, options);
  return res.status(httpStatus.OK).send({ results: messages });
});

